interface.definition:
a!localVariables(
  local!isOldVersion:if(
    a!isNullOrEmpty(ri!nomination.createdOn),
    false,
    if(
      todatetime(ri!nomination.createdOn)<#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11589045",
      true,
      false)
  ),
  local!isRequestBeforeV4:if(
    a!isNullOrEmpty(ri!nomination.createdOn),
    false,
    if(
      todatetime(ri!nomination.createdOn)<#"_a-0000eab6-1962-8000-9c4d-011c48011c48_12333392",
      true,
      false)
  ),
  local!candidateRole:index(#"_a-0000e6d2-8270-8000-9c03-011c48011c48_3924363"(employeeId: ri!nomination.employeeId),"jobFamily",null),
  local!regionId:if(
    toboolean(local!isOldVersion)=true,
    if(
    ri!nomination.returnRegion = #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206267"[1],
    #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206289",
    if(
      ri!nomination.returnRegion = #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206267"[2],
      #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206296",
      null
    )
    ),
    #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11596299"),
    local!oldBU,
    local!oldOffice,
  local!regionDropdown: {
    #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206267"[1],
    #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3206267"[2],
    #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3566688",
    #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3566706",
    #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
    #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3197185"
  },
  local!updatedRegionDropdown: if(
    contains(local!regionDropdown, ri!nomination.returnRegion),
    local!regionDropdown,
    reject(
      fn!isnull,
      append(local!regionDropdown, ri!nomination.returnRegion)
    )
  ),
  local!buId: 
  intersection(
    tointeger(
      property(
        index(
          ri!bu,
          wherecontains(
            ri!nomination.returnBU,
            touniformstring(index(ri!bu,"bu",{}))
          ),
          null
        ),
        "buId",
        null
      )),
      tointeger(property(
        index(
          ri!bu,
          wherecontains(
            tostring(local!regionId),
            touniformstring(index(ri!bu,"regionId",{}))
          ),
          null
        ),
        "buId",
        null
      ))
  ),
  local!busForDropdown: if(
    a!isNullOrEmpty(local!regionId),
    {#"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630", #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3197185"},
    touniformstring(
      property(
        index(
          ri!bu,
          wherecontains(
            tointeger(local!regionId),
            tointeger(index(ri!bu,"regionId",{}))
          ),
          null
        ),
        "bu",
        {}
      ),
      if(toboolean(local!isOldVersion)=true,#"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",null),
      #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3197185"
    )
  ),
  local!updatedBUDropdown: if(
    contains(local!busForDropdown, ri!nomination.returnBU),
    local!busForDropdown,
    if(
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!oldBU),
    reject(
      fn!isnull,
      append(local!busForDropdown, ri!nomination.returnBU)
    ),
    local!busForDropdown
    )
  ),
  local!officesForDropdown: if(
    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!regionId),
    union(
      index(ri!offices,"office",null),
      touniformstring({})
    ),
    property(
      index(
        ri!offices,
        wherecontains(
          local!buId,
          tointeger(index(ri!offices,"buId",{}))
        ),
        null
      ),
      "office",
      {}
    )
  ),
  local!homeOfficeDropdown: reject(
    fn!isnull,
    {local!officesForDropdown, #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3197185", #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630"}
  ),
  local!updatedHomeOfficeDropdown: if(
    contains(local!homeOfficeDropdown, ri!nomination.returnHomeOffice),
    local!homeOfficeDropdown,
    if(
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!oldOffice),
    reject(
      fn!isnull,
      append(local!homeOfficeDropdown, ri!nomination.returnHomeOffice)
    ),
    local!homeOfficeDropdown
    )
  ),
  local!applicablePathways: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050345"(
    refTypeId : 31,
    returnCDT: true(),
    isActive: true()
  ),
  #"SYSTEM_SYSRULES_cardLayout"(
    contents: {
      #"SYSTEM_SYSRULES_sectionLayout_v1"(
        contents: {
          #"SYSTEM_SYSRULES_cardLayout"(           
            contents: {
              #"SYSTEM_SYSRULES_sideBySideLayout"(              
                items: {
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      labelPosition: "COLLAPSED",
                      value: {
                        #"SYSTEM_SYSRULES_richTextIcon"(
                          icon: "exclamation-circle",
                          color: "NEGATIVE",
                          size: "MEDIUM"
                        )
                      }
                    ),
                    width: "MINIMIZE"
                  ),
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      labelPosition: "COLLAPSED",
                      value: {                      
                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: {
                            "Originating Audit BU and Returning Audit BU are different"
                          },
                          style: "STRONG"
                        )                   
                      }
                    )
                  )
                },
                alignVertical: "MIDDLE",
                spacing: "STANDARD"
              )
            },
            showWhen: or(
              and(
                #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.otherOriginatingBU),
                #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.otherReturningBU),
                ri!nomination.otherOriginatingBU<>ri!nomination.otherReturningBU
              ),
              and(
                #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.originatingBU),
                #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.returnBU),
                ri!nomination.originatingBU<>ri!nomination.returnBU
              )
            ),
            style: "ERROR",
            marginBelow: "STANDARD",
            accessibilityText: "Error message"
          ),
          #"SYSTEM_SYSRULES_cardLayout"(           
            contents: {
              #"SYSTEM_SYSRULES_sideBySideLayout"(              
                items: {
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      labelPosition: "COLLAPSED",
                      value: {
                        #"SYSTEM_SYSRULES_richTextIcon"(
                          icon: "exclamation-circle",
                          color: "NEGATIVE",
                          size: "MEDIUM"
                        )
                      }
                    ),
                    width: "MINIMIZE"
                  ),
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      labelPosition: "COLLAPSED",
                      value: {                      
                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: {
                            "Originating Home Office and Returning Home Office are different"
                          },
                          style: "STRONG"
                        )                   
                      }
                    )
                  )
                },
                alignVertical: "MIDDLE",
                spacing: "STANDARD"
              )
            },
            showWhen: or(
              and(
                #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.originatingHomeOffice),
                #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.otherReturningHomeOffice),
                ri!nomination.otherOriginatingHomeOffice<>ri!nomination.otherReturningHomeOffice
              ),
              and(
                #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.originatingHomeOffice),
                #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.returnHomeOffice),    
                ri!nomination.originatingHomeOffice<>ri!nomination.returnHomeOffice
              )
            ),
            style: "ERROR",
            marginBelow: "STANDARD",
            accessibilityText: "Error message"
          ),
          #"SYSTEM_SYSRULES_columnsLayout"(
            columns: {
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_dropdownField_v1"(
                    label: if(
                      and(
                        or(
                          ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4147895",
                          ri!nomination.positionTypeId = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699"
                        ),
                        not(ri!nomination.isDirectHire = true)
                      ),
                      "Returning Region *",
                      "Returning Region"
                    ),
                    placeholder: "-- Select --",
                    choiceLabels: local!updatedRegionDropdown,
                    choiceValues:  local!updatedRegionDropdown,
                    value: ri!nomination.returnRegion,
                    saveInto: {
                      ri!nomination.returnRegion,
                      if(
                        contains(
