                          ri!nomination.positionTypeId = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699"
                        ),
                        not(ri!nomination.isDirectHire = true)
                      ),
                      "Returning Audit BU *",
                      "Returning Audit BU"
                    ),
                    placeholder: "-- Select --",
                    choiceLabels: reject(fn!isnull,local!updatedBUDropdown),
                    choiceValues: reject(fn!isnull,local!updatedBUDropdown),
                    value: ri!nomination.returnBU,
                    saveInto: {
                      if(#"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(local!oldBU),a!save(local!oldBU,ri!nomination.returnHomeOffice),{}),
                      a!save(ri!nomination.returnHomeOffice,null),
