                        {}
                      )
                    },
                    required: and(
                      or(
                        ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4147895",
                        ri!nomination.positionTypeId = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699"
                      ),
                      not(ri!nomination.isDirectHire = true)
                    ),
                    validations: if(
                      or(
                        contains(local!busForDropdown, ri!nomination.returnBU),
                        a!isNullOrEmpty(ri!nomination.returnBU)
                      ),
                      "",
                      "Please select a valid returning Audit BU"
                    ),
                    validationGroup: "main"
                  ),
                  #"SYSTEM_SYSRULES_dropdownField_v1"(
                    label: if(
                      and(
                        or(
                          ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4147895",
                          ri!nomination.positionTypeId = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699"
                        ),
                        not(ri!nomination.isDirectHire = true)
                      ),
                      "Returning Home Office *",
                      "Returning Home Office"
                    ),
                    placeholder: "-- Select --",
                    choiceLabels: local!updatedHomeOfficeDropdown,
                    choiceValues: local!updatedHomeOfficeDropdown,
                    value: ri!nomination.returnHomeOffice,
                    saveInto: {
                      a!save(local!oldOffice,ri!nomination.returnHomeOffice),
                      ri!nomination.returnHomeOffice,
                      if(
                        ri!nomination.returnHomeOffice <> #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
                        a!save(ri!nomination.otherReturningHomeOffice,null),
                        {}
                      )
                    },
                    required: and(
                      or(
                        ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4147895",
                        ri!nomination.positionTypeId = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699"
                      ),
                      not(ri!nomination.isDirectHire = true)
                    ),
                    validations: if(
                      or(
                        contains(local!homeOfficeDropdown, ri!nomination.returnHomeOffice),
                        a!isNullOrEmpty(ri!nomination.returnHomeOffice)
                      ),
                      "",
                      "Please select a valid returning home office"
                    ),
                    validationGroup: "main"
                  )
                }
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_textField"(

                    showWhen: if(toboolean(local!isOldVersion)=true,true,false),
                    label: if(
                      ri!nomination.returnRegion = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
                      "Other Returning Region *",
                      "Other Returning Region"
                    ),
                    value: ri!nomination.otherReturningRegion,
                    saveInto: ri!nomination.otherReturningRegion,
                    characterLimit: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958020",
                    required: ri!nomination.returnRegion = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
                    disabled: ri!nomination.returnRegion <> #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
                    validationGroup: "main"
                  ),
                  #"SYSTEM_SYSRULES_textField"(
                    label: if(
                      ri!nomination.returnBU = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
                      "Other Returning Audit BU *",
                      "Other Returning Audit BU"
                    ),
                    value: ri!nomination.otherReturningBU,
                    saveInto: ri!nomination.otherReturningBU,
                    characterLimit: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958020",
                    required: ri!nomination.returnBu = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
                    disabled: ri!nomination.returnBU <> #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
                    validationGroup: "main"
                  ),
                  #"SYSTEM_SYSRULES_textField"(
                    label: if(
                      ri!nomination.returnHomeOffice = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
                      "Other Returning Home Office *",
                      "Other Returning Home Office"
                    ),
                    value: ri!nomination.otherReturningHomeOffice,
                    saveInto: ri!nomination.otherReturningHomeOffice,
                    characterLimit: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3958020",
                    required: ri!nomination.returnHomeOffice = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
                    disabled:  ri!nomination.returnHomeOffice <> #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
                    validationGroup: "main"
                  )
                }
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnsLayout"(
            columns: {
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_textField"(
                    label: if( 
                      ri!nomination.isDirectHire = true,
                      "Years With Firm",
                      "Years With Firm *"
                    ),
                    value: tointeger(ri!nomination.yearsWithFirm),
                    saveInto: ri!nomination.yearsWithFirm,
                    required: not(ri!nomination.isDirectHire = true),
                    validations: if(
                      or(
                        tointeger(ri!nomination.yearsWithFirm) >= 40,
                        tointeger(ri!nomination.yearsWithFirm) <= 0
                      ),
                      "Please provide a number between 1-40",
                      ""
                    ),
                    validationGroup: "main"
                  ),
                  #"SYSTEM_SYSRULES_dropdownField_v1"(
                    label: if(
                      or(
                        ri!nomination.isDirectHire = true,
                        ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148695",
                        ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148688"
                      ),
                      "Expected MD Promotion Date",
                      "Expected MD Promotion Date *"
                    ),
                    placeholder: "-- Select --",
                    choiceLabels: ri!promotionDate.display,
                    choiceValues: ri!promotionDate.year,
                    value: ri!nomination.mdPromotionDate,
                    saveInto: ri!nomination.mdPromotionDate,
                    required: not(
                      or(
                        ri!nomination.isDirectHire = true,
                        ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148695",
                        ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148688"
                      )
                    ),
                    disabled: or(
                      /*ri!nomination.isDirectHire = true,*/
                      ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148688",
                      ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148695"
                    ),
                    validationGroup: "main"
                  ),
                  #"SYSTEM_SYSRULES_paragraphField"(
                    label: "Expected MD Promotion Date Comments",
                    placeholder: "Comment for MD promotion date",
                    value: ri!nomination.mdPromotionDateComment,
                    saveInto: ri!nomination.mdPromotionDateComment,
                    characterLimit: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3238137",
                    disabled: or(
                      ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148688",
                      ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148695"
                    )
                  ),
                  #"SYSTEM_SYSRULES_paragraphField"(
                    label: if(
                      ri!nomination.isDirectHire = true,
                      "Rationale For Nomination",
                      "Rationale For Nomination *"
                    ),
                    placeholder: "Comment for rationale for nomination",
                    value: ri!nomination.rationalForNomination,
                    saveInto: ri!nomination.rationalForNomination,
                    characterLimit: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3238137",
                    required: not(ri!nomination.isDirectHire = true),
                    validationGroup: "main"
                  )
                }
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  /* Sahana Ananth -- added applicable pathway and pathway comments fields as part of APAP-28578 on 4-Nov-25*/
                  #"SYSTEM_SYSRULES_dropdownField_v1"(
                    label: "Which pathway is most applicable to the candidate?",
                    instructions: "Note: All traditional w/ EQCR rotationals are expected to be an MD and designated on the 'Public' pathway.",
                    choiceLabels: index(local!applicablePathways,"description",null),
                    choiceValues: index(local!applicablePathways,"description",null),
                    value: index(ri!nomination,"applicablePathway",null),
                    saveInto: ri!nomination.applicablePathway,
                    placeholder: "--Select a value--",
                    required: true()
                  ),
                  #"SYSTEM_SYSRULES_paragraphField"(
                    label: "Pathway Comments",
                    value: index(ri!nomination,"pathwayComments",null),
                    saveInto: ri!nomination.pathwayComments,
                    characterLimit: 250
                  ),
                  if(
                    toboolean(local!isOldVersion)=true,
                    #"SYSTEM_SYSRULES_dropdownField_v1"(
                      label: if(
                        or(
                          ri!nomination.isDirectHire = true,
                          ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148688"
                        ),
                        "Expected Partner Promotion Date",
                        "Expected Partner Promotion Date *"
                      ),
                      placeholder: "-- Select --",
                      choiceLabels: ri!promotionDate.display,
                      choiceValues: ri!promotionDate.year,
                      value: ri!nomination.partnerPromotionDate,
                      saveInto: ri!nomination.partnerPromotionDate,
                      required: not(
                        or(
                          ri!nomination.isDirectHire = true,
                          ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148688"
                        )
                      ),
                      disabled: ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148688",
                      validationGroup: "main"
                    ),
                    {
                      /*a!textField(*/
                      /*readOnly: true,labelPosition: "ADJACENT"*/
                      /*),*/
                      #"SYSTEM_SYSRULES_radioButtonField"(
                        label: if(toboolean(local!isRequestBeforeV4),
                        "Is this candidate a future partner promote?",
                        "Is this candidate in your partner pipeline?"),
                        required: if(
                          toboolean(local!isRequestBeforeV4),
                          true,
                          if(
                            or(
                              local!candidateRole ="Partner",
                              and(ri!nomination.isDirectHire=true, ri!nomination.isDirectHireInternal=false, ri!nomination.levelName="Partner")
                            ),

                            false,
                            true
                          )

                        ),
                        choiceLabels: {"Yes","No"},
                        choiceValues: {true,false},
                        value:ri!nomination.isFuturePartnerPromote,
                        saveInto: {
                          ri!nomination.isFuturePartnerPromote,
                        },
                        choiceLayout: "COMPACT"
                      )}
                      ,
                  ),
                  #"SYSTEM_SYSRULES_paragraphField"(
                    label: if( toboolean(local!isOldVersion)=true,
                    "Expected Partner Promotion Date Comments","Future Partner Promotion Date Comments"),
                    placeholder: if( toboolean(local!isOldVersion)=true,
                    "Comment for partner promotion date","Comment for future partner promotion date"),
                    value: ri!nomination.partnerPromotionDateComment,
                    saveInto: ri!nomination.partnerPromotionDateComment,
                    characterLimit: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3238137",
